installer-gui-script:
    Surehand MCP









function checkOS() {
    // the bundled Node.js 24 needs macOS 13.5 or later
    if (system.compareVersions(system.version.ProductVersion, '13.5') < 0) {
        my.result.type = 'Fatal';
        my.result.title = 'macOS 13.5 or later is required';
        my.result.message = 'Surehand MCP needs macOS Ventura 13.5 or later.';
        return false;
    }
    return true;
}

// Where each AI app is looked for (installer/ai-apps.json "mac"; ~ is the home folder). The server checks the same
// when it connects an app.
var APP_PATHS = @APP_PATHS@;
function found(id) {
    var home = system.env.HOME || '';
    var paths = APP_PATHS[id] || [];
    for (var i = 0; i < paths.length; i++) {
        var p = paths[i].charAt(0) == '~' ? home + paths[i].substring(1) : paths[i];
        if (system.files.fileExistsAtPath(p)) return true;
    }
    return false;
}


